(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sw"] = {"ui":{"skip":"Ruka hadi maudhui","back":"← Rudi kwenye AI-gile","lang.button":"Lugha: {name}","lang.dialog":"Chagua lugha","lang.search":"Tafuta lugha","lang.none":"Hakuna lugha inayolingana","lang.notYet":"{name} haijatafsiriwa bado","theme.aria":"Badilisha mandhari: angavu, meusi au nyeusi tupu","theme.toLight":"Badili kwenda mandhari angavu","theme.toDark":"Badili kwenda mandhari meusi","theme.toBlack":"Badili kwenda mandhari ya rangi nyeusi tupu (nyeusi halisi, rafiki kwa skrini za OLED)","words.underline":"Pigia mstari maneno haya kwenye ukurasa","words.underlineHelp":"Weka kipanya juu ya neno lenye vitone au uliguse ili uone maana yake.","index.title":"AI-gile: timu yako ya AI ya wasanidi, kwenye ubao mmoja","index.description":"AI-gile ni ubao wa kanban kwa timu za AI zinazoandika msimbo. Hufanya kazi wakati umelala; wewe unapata rundo moja fupi la mambo ya kuamua, kujaribu na kukubali.","hero.logoAlt":"Ikoni ya ubao wa AI-gile","hero.h1.html":"Timu yako ya AI ya wasanidi, kwenye ubao&nbsp;mmoja.","hero.alpha":"🐣 Pre-alpha iliyofungwa","hero.alphaTitle":"Bado mapema na haijakamilika: asante kwa kujaribu!","hero.lede":"Wanajenga wakati umelala. Unaamka kukuta rundo moja fupi: maswali machache, mambo machache ya kujaribu, almasi moja au mbili za zambarau. Bofya, kubali, rudi kwenye kahawa yako.","dl.windows":"Programu ya Windows","dl.browser":"Iendeshe kwenye kivinjari","dl.messenger":"📱 Messenger kwa simu yako","dl.soon":"Inakuja hivi karibuni","dl.notify":"🔔 Niambie itakapofunguliwa","dl.notifySmall":"Alpha au beta","hero.secondary":"Agile, lakini timu haihitaji kahawa ya stand-up kamwe. (Hufanya stand-up hata hivyo.)","pitch.h2":"AI-gile kwa maneno mengi kadri upendavyo","pitch.lede":"Chagua urefu, kuanzia neno moja hadi 144. Kila urefu ni maelezo yake yenyewe, yaliyoandikwa kwa ukubwa huo. Buruta kitelezi au tumia vitufe vya mishale.","pitch.rangeLabel":"Urefu kwa maneno","pitch.dice":"🎲 toleo jingine","pitch.words.one":"neno {n}","pitch.words.other":"maneno {n}","pitch.letters.one":"herufi {n}","pitch.letters.other":"herufi {n}","pitch.chars.one":"kibambo {n}","pitch.chars.other":"vibambo {n}","count.line.html.one":"kadi {n} kwenye ubao sasa hivi","count.line.html.other":"kadi {n} kwenye ubao sasa hivi","people.humans.html.one":"👥 binadamu {n}","people.humans.html.other":"👥 binadamu {n}","people.agents.html.one":"🤖 wakala {n}","people.agents.html.other":"🤖 mawakala {n}","people.working.html.one":"⚡ {n} anafanya kazi sasa hivi","people.working.html.other":"⚡ {n} wanafanya kazi sasa hivi","pre.title":"AI-gile: kuna kitu kinajengwa","pre.description":"Kuna kitu kinajengwa hapa: ubao ambapo timu za AI zinajenga unachoomba, na kukufundisha zikiendelea. Kwa sasa ni pre-alpha iliyofungwa na marafiki.","pre.h1":"Kuna kitu kinajengwa hapa. 🤫","pre.line":"Ubao ambapo timu za AI zinajenga unachoomba, na kukufundisha zikiendelea. Kwa sasa ni pre-alpha iliyofungwa na marafiki.","pre.btn":"🔔 Niambie itakapofunguliwa","pre.peek":"Nyuma ya kioo: ubao halisi, moja kwa moja. Kila kadi ni mstari wa rangi.","pre.peekFake":"Nyuma ya kioo: hivi ndivyo ubao kazini unavyoonekana.","features.aria":"Inafanya nini","f.pile.h":"Rundo moja kwa ajili yako","f.pile.html":"<b>Kwako</b> hushikilia kila kitu kinachokusubiri, kwenye kila mradi: maswali, mambo ya kujaribu, kazi ambazo binadamu pekee anaweza kuzifanya. Foleni yako inaonyesha kinachofuata na kitachukua muda gani.","f.sleep.h":"Timu zinazofanya kazi ukiwa umelala","f.sleep.p":"Kila mradi una kiongozi na timu ya mawakala wa AI. Toa maoni kwenye kadi na timu inaamka, inafanya kazi, na kuirudisha pamoja na hatua ambazo binadamu aliyechoka anaweza kuzifuata.","f.tester.h":"Mjaribu wa AI hukagua kwanza","f.tester.p":"Kabla ya chochote kukufikia, mjaribu hufuata hatua kwenye nakala ya programu na kuonyesha alichokiona, pamoja na picha ya skrini. Pitia zile zilizofaulu na ukubali kwa bofya moja.","f.proof.h":"Ushahidi, si ahadi","f.proof.p":"Kila makabidhiano yanaonyesha kilichobadilika: faili, tofauti, picha za skrini. Huhitaji kufungua kila programu kuona kama imekamilika.","f.chat.h":"Piga gumzo na viongozi wako","f.chat.p":"Safu kama ya Discord: ikoni moja kwa kila mradi, almasi za zambarau kwa kinachokuhitaji. Mwandikie kiongozi wazo; analigeuza kuwa kadi na mpango, pamoja na kitufe cha ✅ Anza.","f.tidy.h":"Hujipanga yenyewe","f.tidy.p":"Kadi zinazohusiana huunganishwa kuwa moja, vichwa vilivyochanganyika hurekebishwa, na ukaguzi wa tokeni huweka msimbo mwepesi. Mambo machache ya kubadilisha kati yake, machache ya kufikiria.","f.private.h":"Yako, kwenye kompyuta yako","f.private.li1":"Ubao huendeshwa kwenye kompyuta yako mwenyewe na hukujibu wewe tu.","f.private.li2":"Ujumbe wa faragha kati ya watu umesimbwa kutoka mwanzo hadi mwisho.","f.private.li3":"Hakuna akaunti, hakuna vifuatiliaji, hakuna vidakuzi.","f.lang.h":"Kwa lugha yako","f.lang.p":"Zaidi ya lugha 120, kuanzia Kiholanzi, Kiwelisi na Kijapani hadi maharamia, Yoda na Kiklingoni, na kubadili haraka kurudi Kiingereza kwa maneno ya kitaalamu.","f.service.h":"Kutoka wazo hadi huduma halisi","f.service.p":"Umejenga kitu kwa AI ambacho watu sasa wanakitumia? Kiwekee alama kama huduma na ubao utakusaidia kukiendesha vizuri: ukaguzi wa upatikanaji, ukurasa wa hali wa umma, matukio yenye uchambuzi, mabadiliko yanayohitaji Go, nakala rudufu zinazokaguliwa kila siku. Msaada hukufundisha kila hatua unapoendelea.","msgr.h2":"AI-gile Messenger: timu yako mfukoni mwako","msgr.p1":"Ongea na timu yako ya AI bila kufungua ubao. Piga gumzo na viongozi wa miradi yako na marafiki zako, uone hatua za majaribio za kadi na uzijibu, yote kutoka kwenye simu yako.","msgr.p2":"Ili kuiunganisha, changanua msimbo wa QR kwenye ubao wako. Mara ya kwanza? Gumzo la onyesho la kirafiki litakuonyesha kila kitu.","msgr.when":"Android kwanza, kisha toleo la wavuti kwa simu na iPhone.","msgr.who":"Kiongozi wa mradi wako","msgr.b1":"Marekebisho ya hali ya giza yako tayari. Unataka hatua za majaribio?","msgr.b2":"Ndiyo tafadhali!","msgr.b3":"1. Fungua Mipangilio. 2. Chagua Giza. Inaonekana sawa?","tl.aria":"Ratiba ya matukio kuanzia mazungumzo ya kwanza hadi mpango wa mbele","tl.h2":"Kuanzia gumzo la kwanza hadi yajayo","tl.lede":"Tarehe na saa halisi, katika saa za eneo lako. Baada ya leo ni mpango, bila tarehe za ahadi.","tl.today":"Leo","tl.planned":"imepangwa","tl.cards.one":"kadi {n}","tl.cards.other":"kadi {n}","join.h2":"Jiunge nasi","join.lede":"AI-gile inajengwa na mtu wa ajabu mwenye ndevu, mwenye AuDHD na mapambano kadhaa ya afya ya akili, pamoja na mawakala wengi wenye subira. Kwa sasa ni ya faragha, kwenye alpha iliyofungwa na marafiki. Ungependa kujaribu itakapofunguliwa?","join.btn":"Onyesha nia","join.small":"Tutakutumia barua pepe, hakuna kingine","footer.tag":"AI-gile. Hakuna vifuatiliaji, hakuna vidakuzi, hakuna kahawa ya stand-up.","footer.licence":"Leseni ya biashara","footer.status":"Hali","footer.privacy":"Tunachohifadhi","footer.thanks":"Simu kwa hisani ya ChilledChat","form.sending":"Inatuma…","form.failed":"Haikufanikiwa: jaribu tena baadaye.","form.offline":"Imeshindwa kufikia AI-gile: jaribu tena baadaye.","form.keep":"Tunatumia hiki tu kukujibu, kisha tunakifuta. Hakuna vifuatiliaji, hakuna vidakuzi.","form.keepLink":"Tunachohifadhi","interest.title":"AI-gile: niambie alpha itakapofunguliwa","interest.description":"Acha barua pepe yako ujue alpha au beta iliyofungwa ya AI-gile itakapofunguliwa.","interest.h1":"🔔 Niambie itakapofunguliwa","interest.lede":"AI-gile iko kwenye pre-alpha iliyofungwa. Acha barua pepe yako nasi tutakuandikia mara moja, kukiwa na nafasi kwako.","interest.email":"Barua pepe yako","interest.which":"Jaribio lipi?","interest.alpha":"Alpha iliyofungwa: mapema, changa, mabadiliko mengi","interest.beta":"Beta: thabiti zaidi, baadaye","interest.both":"Lolote, lile litakalokuja kwanza","interest.submit":"Niweke kwenye orodha","interest.thanks":"Asante! Uko kwenye orodha.","licence.title":"AI-gile: leseni ya biashara","licence.description":"Unatumia AI-gile kwenye biashara yako? Omba leseni ya biashara ya bure.","licence.h1":"📜 Leseni ya biashara","licence.lede":"Unatumia AI-gile kazini? Tuambie wewe ni nani na unafanya nini. Ikifanya mema, leseni ni bure.","licence.company":"Kampuni","licence.website":"Tovuti","licence.what":"Unachofanya","licence.how":"Inavyosaidia dunia","licence.email":"Barua pepe","licence.submit":"Omba","licence.thanks":"Asante! Tutajibu kwa barua pepe.","status.title":"Hali ya AI-gile","status.h1":"Hali ya AI-gile","status.quiet":"Kimya kabisa","status.intro":"Je, AI-gile inafanya kazi sasa hivi? Ukurasa huu hukagua tovuti, kushiriki mbao, simu na upakuaji kila baada ya dakika 5.","status.up":"Inafanya kazi (ilijibu ndani ya {ms} ms)","status.slow":"Haikujibu ukaguzi uliopita, inajaribu tena","status.down":"Haifanyi kazi: haikujibu ukaguzi wa mara mbili zilizopita","status.svc.web":"Tovuti","status.svc.web.offers":"Tovuti hii: AI-gile ni nini, na fomu ya kuonyesha nia","status.svc.boards":"Kushiriki mbao","status.svc.boards.offers":"Mbao za umma, ujumbe kati ya marafiki na mialiko","status.svc.calls":"Simu","status.svc.calls.offers":"Sauti, video na kushiriki skrini ndani ya AI-gile","status.svc.download":"Upakuaji","status.svc.download.offers":"Kisakinishi cha Windows na viungo vya mialiko","status.checking":"Inakagua…","status.offline":"Huduma ya hali haipatikani sasa hivi (inajaribu tena)","status.updated":"imesasishwa {ago}","status.justNow":"sasa hivi","status.min":"dakika {n} zilizopita","status.hours":"saa {n} zilizopita","status.days":"siku {n} zilizopita","privacy.title":"AI-gile: tunachohifadhi","privacy.h1":"Tunachohifadhi","privacy.lede":"Kwa kifupi: ni kile unachotutumia tu, na si kwa muda mrefu.","privacy.only":"Ni kile unachotutumia tu: unachoandika kwenye fomu, kama barua pepe yako. Hakuna kingine kukuhusu.","privacy.sealed":"Kinafungwa kwa muhuri ili seva yetu isiweze kukisoma: kwenye kivinjari chako kabla hakijaondoka (kwenye kivinjari cha zamani, mara tu kinapofika). Ni ubao wetu pekee unaoweza kukifungua.","privacy.server":"Kinafutwa kwenye seva mara tu kinapofika kwenye ubao wetu. Chochote kinachobaki huko baada ya siku 30 kinafutwa hata hivyo.","privacy.board":"Tunakihifadhi kwenye ubao wetu hadi tutakapokujibu tu, kisha tunakifuta huko pia.","privacy.none":"Hakuna vifuatiliaji, hakuna vidakuzi, hakuna takwimu za matumizi.","privacy.local":"Lugha yako na chaguo lako la mwanga au giza hubaki kwenye kivinjari chako. Havitumwi kwetu kamwe.","privacy.ask":"Ungependa kifutwe mapema zaidi? Jibu barua pepe yetu na utuambie.","live.h2":"Itazame ikijengwa, moja kwa moja","live.caption":"Kila kadi imefichwa: unaona umbo la kazi, si maneno.","live.watching.one":"moja kwa moja: {n} wanatazama","live.watching.other":"moja kwa moja: {n} wanatazama","live.last.now":"Kadi ya mwisho ilihamishwa muda mfupi uliopita","live.last.min.one":"Kadi ya mwisho ilihamishwa dakika {n} iliyopita","live.last.min.other":"Kadi ya mwisho ilihamishwa dakika {n} zilizopita","live.last.hour.one":"Kadi ya mwisho ilihamishwa saa {n} iliyopita","live.last.hour.other":"Kadi ya mwisho ilihamishwa saa {n} zilizopita","live.last.day.one":"Kadi ya mwisho ilihamishwa siku {n} iliyopita","live.last.day.other":"Kadi ya mwisho ilihamishwa siku {n} zilizopita","live.offline":"Ubao wa moja kwa moja unapumzika kidogo. Rudi tena hivi karibuni.","live.cols":"Backlog|Za kufanya|Zinaendelea|Timu inakagua|Zako za kujaribu|Kwa timu|Zimekamilika"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Kukabidhi."]},{"n":2,"texts":["Kanban, kiotomatiki.","Mawakala, wamepangika.","Mawazo, yamejengwa."]},{"n":3,"texts":["Kanban ya roboti.","Mawazo yanakuwa vipengele.","Kanban ya mawakala, bure."]},{"n":5,"texts":["Ubao wa kanban unaoendeshwa na mawakala.","Wewe andika kadi. Mawakala wanajenga.","Bure, binafsi, imejaribiwa, kidogo kichekesho."]},{"n":8,"texts":["Ubao wa bure wa kanban wenye mawakala wa AI.","Andika wazo. Mawakala wanalijenga. Wewe unakubali.","Agile kwa binadamu mmoja na roboti wengi wenye subira."]},{"n":13,"texts":["Ubao wa kanban kwenye kompyuta yako ambapo mawakala wa AI huchukua kadi na kujenga.","Andika wazo. Timu ya mawakala inalijenga. Mjaribu analikagua, kisha wewe unaamua.","Bure, bila akaunti wala vifuatiliaji: ubao, roboti kadhaa, na wewe ukiwa kiongozi."]},{"n":21,"texts":["AI-gile ni ubao wa kanban wa kufanya kazi na mawakala wa AI wanaoandika msimbo. Wao huchukua kadi; wewe unazijaribu na kuzikubali.","Kila mradi unapata kiongozi na timu ya mawakala wa AI. Toa maoni kwenye kadi yoyote na timu inaanza kazi.","Ubao wa majukumu wa bure na binafsi unaoendeshwa kwenye kompyuta yako mwenyewe. Wafanyakazi ni roboti. Anayesema ndiyo ni wewe."]},{"n":34,"texts":["Unaweka mawazo kwenye ubao. Timu ya mawakala wa AI inayageuza kuwa vipengele vinavyofanya kazi, inavijaribu, na kukurudishia pamoja na hatua za kujaribu. Hakuna kinachohesabiwa kuwa kimekamilika hadi useme.","AI-gile ni ubao wa kanban uliotengenezwa nyumbani ambao Rich aliujenga kwa msaada mkubwa wa mawakala anaowasimamia sasa. Ni wa bure, huendeshwa kwenye kompyuta yako, na hushirikiwa na marafiki, hauuzwi.","Fikiria ubao wa kawaida wa kanban, wenye safu kutoka Backlog hadi Zimekamilika, isipokuwa kadi zinachukuliwa na mawakala wa AI. Wanaripoti maendeleo, wanauliza wanapokwama, na daima wanasubiri kidole chako gumba juu."]},{"n":55,"texts":["AI-gile ni ubao wa kanban ambapo timu inaundwa na mawakala wa AI. Kila mradi una kiongozi anayepanga kazi na wasaidizi wanaojenga. Kipengele kikiwa tayari, mjaribu wa AI analijaribu na kupiga picha ya skrini, kisha kinatua kwenye rundo lako. Kikubali, au toa maoni nao wakifanyie kazi upya.","Ilianza kama njia ya mtu mmoja ya kufuatilia vikao vingi vya AI vya kuandika msimbo kwa wakati mmoja, kisha ikakua kuwa ubao kamili. Inaendeshwa kwenye kompyuta yako, haihitaji akaunti, na haina vifuatiliaji. Ni ya bure kwa marafiki na wadadisi. Pia haijakamilika, kwa hiyo tarajia kasoro na mshangao mara moja moja.","Hili hapa toleo la ukweli. Bado ni wewe unayehitaji kuwa na mawazo, na bado ni wewe unayekagua matokeo. AI-gile hufanya kila kitu kilicho katikati: huweka kadi kwa mpangilio, huamsha wakala sahihi unapotoa maoni, huonyesha hasa kilichobadilika, na hukusanya yote kwenye rundo moja fupi kwa ajili yako."]},{"n":89,"texts":["AI-gile ni ubao wa kanban wa bure unaouendesha kwenye kompyuta yako mwenyewe. Badala ya watu, kila mradi una timu ya mawakala wa AI: kiongozi anayegeuza mawazo yako kuwa kadi na mpango, na wasaidizi wanaochukua kadi kwa mpangilio wa kipaumbele. Kitu kikijengwa, mjaribu wa AI hufuata hatua za majaribio na kukuonyesha alichokiona. Kisha kinasubiri kwenye rundo moja liitwalo Kwako. Unakikubali, au unatoa maoni na timu inajaribu tena. Hakuna kitu kinachofika Zimekamilika bila wewe.","Kuna mambo kadhaa ambayo huenda hukuyatarajia. Mlinzi wa usiku hujaza safu ya Za kufanya ukiwa umelala, akichagua kadi zisizohitaji jibu kutoka kwako. Kihesabu cha tokeni kinaonyesha mawakala wametumia kiasi gani leo na wiki hii, na No Token Mode huwaambia waache kutumia. Unaweza kuwatumia marafiki ujumbe, na ujumbe wa faragha umesimbwa kutoka mwanzo hadi mwisho. Ubao huzungumza takriban lugha 120, zikiwemo Kiholanzi, Kiflemi, maharamia na Kiklingoni. Hakuna hata kimoja kinachogharimu senti, na hakuna anayejaribu kukuuzia chochote pia.","AI-gile ni mradi mdogo, binafsi, si kampuni. Rich alitaka kutunza miradi kadhaa ya AI ya kuandika msimbo bila kufungua kila programu kuangalia hali, kwa hiyo yeye na mawakala wakajenga ubao kwa ajili hiyo, kisha wakautumia ubao huo kujenga sehemu iliyobaki yake. Uko kwenye pre-alpha iliyofungwa, yaani unafanya kazi, kwa kiasi kikubwa, kwa marafiki wachache. Hakuna ukurasa wa bei, hakuna jarida na hakuna mpango wa kukua. Ukionekana kukufaa, unaweza kuomba kujaribu utakapofunguliwa zaidi kidogo."]},{"n":144,"texts":["AI-gile ni ubao wa kanban kwa binadamu mmoja na mawakala wengi wa AI. Unaendeshwa kwenye kompyuta yako mwenyewe na ni wa bure kabisa. Unaongeza miradi, na kila mradi unapata kiongozi na timu ndogo. Unapiga gumzo na kiongozi, kama vile Discord, na kueleza wazo; kiongozi analigeuza kuwa kadi na mpango, kisha anasubiri ubonyeze Anza. Timu inapitia kadi kwa mpangilio wa kipaumbele, ikitumia zana rahisi ya mstari wa amri iliyotengenezwa kwa miundo ya lugha. Kabla chochote hakijakurudia, mjaribu wa AI hufuata hatua kwenye nakala ya programu na kuambatisha picha ya skrini. Kazi iliyokamilika inatua kwenye rundo lako pamoja na faili zilizobadilika na tofauti. Unaikubali, au unaacha maoni na timu inaamka na kujaribu tena. Wewe pekee ndiye unayeweza kuhamisha kadi hadi Zimekamilika.","Siku moja na AI-gile, kwa ufupi. Jioni unaacha maoni machache: kitufe hiki kiko mahali pasipofaa, orodha ile ipangwe, tunaweza kupata hali ya giza. Unaenda kulala. Mawakala wanasoma maoni, wanafanya mabadiliko, wanayajaribu na kukurudishia. Za kufanya zikiisha, mlinzi wa usiku anazijaza kutoka kwenye backlog kwa kadi zisizohitaji jibu lako. Asubuhi kuna rundo moja fupi: maswali machache na mambo kadhaa ya kujaribu, kila moja likiwa na hatua ambazo mtu mwenye usingizi anaweza kuzifuata na picha ya skrini inayoonyesha inafanya kazi. Unapitia, unakubali nzuri na kurudisha zilizobaki. Kihesabu cha tokeni kinaonyesha yote yalitumia kiasi gani, na No Token Mode ipo kwa wiki za kubana matumizi. Kisha unakula kifungua kinywa, ambapo mawakala bado hawawezi kusaidia. Wakati mwingine unaamka na swali la wakala aliyekwama, na unalijibu kwa sentensi moja kabla ya chai. Hakuna mkutano, hakuna barua pepe ndefu, hakuna kuuliza nani alibadilisha nini.","Kwanza, AI-gile si nini. Si kampuni changa, haiuzwi, na hakuna anayekusanya data yako. Ni ubao wa bure unaoendeshwa kwenye kompyuta yako, bila akaunti, bila vifuatiliaji na bila vidakuzi. Ni nini: mahali pamoja pa nadhifu pa kuona miradi yako yote ya AI ya kuandika msimbo kwa wakati mmoja, timu ya mawakala ikifanya kadi na wewe ukifanya maamuzi. Huunganisha kadi zinazohusiana, hurekebisha vichwa vilivyochanganyika, na hufuatilia jinsi msimbo unavyobaki mwepesi. Huzungumza takriban lugha 120, kuanzia Kiholanzi na Kiflemi hadi maharamia na Kiklingoni. Marafiki wanaweza kutumiana ujumbe, kwa faragha na kwa usimbaji. Ilijengwa na Rich na idadi kubwa ya mawakala wenye subira, hasa kwa kujitumia yenyewe. Iko kwenye pre-alpha iliyofungwa, kwa hiyo ina kasoro hapa na pale. Ukiona inavutia, omba kwa adabu na huenda ukaingia mapema."]}],"quips":{"1":"Neno moja. Jasiri. Labda jasiri kupita kiasi.","3":"Maneno matatu. Tayari ni ya kweli kuliko kurasa nyingi za bidhaa.","8":"Maneno manane. Bado ni mafupi kuliko stand-up.","21":"Kwa njia, urefu ni story points. Bila shaka ndivyo.","55":"Maneno hamsini na tano. Kadi mbili zimekamilika ulipokuwa unasoma hili.","144":"Hii ndiyo ndefu. Hakuna 233. Mawakala wamekwenda kulala."}},"timeline":{"first-idea.name":"Wazo la kwanza","first-idea.line":"Mazungumzo ya kwanza kabisa, kabla msimbo wowote haujakuwepo.","first-board.name":"Ubao wa kwanza","first-board.line":"Ubao unaofuatilia ujenzi wake wenyewe: kadi, safu, buruta na dondosha, miradi.","team-roles.name":"Timu na majukumu","team-roles.line":"Wasifu wa mawakala, violezo vya timu, nafasi na nani anafanya nini.","install.name":"Usakinishaji na matoleo","install.line":"Zip ambayo rafiki anaweza kusakinisha, kujisasisha, njia za matoleo na kurudi nyuma.","usage-saver.name":"Kiokoa matumizi","usage-saver.line":"Pima gharama za uendeshaji, weka msimbo mwepesi, okoa kikomo chako.","friends.name":"Marafiki na kushiriki","friends.line":"Ujumbe wa faragha, relay iliyosimbwa, mialiko, majukumu na miradi ya pamoja.","languages.name":"Lugha","languages.line":"Kila maandishi ya skrini kwenye faili la lugha, Kiholanzi na Kiflemi kwanza.","ai-tester.name":"Mjaribu wa AI","ai-tester.line":"Mjaribu hukagua kila makabidhiano kwanza na kuonyesha alichokiona.","website.name":"Tovuti","website.line":"aigile.lol, ukurasa wa utangulizi na ratiba hii.","streaming.name":"Gumzo na utiririshaji","streaming.line":"Discord, Twitch, OBS, hali ya mtiririshaji, GIF na emoji.","no-ai.name":"Toleo bila AI","no-ai.line":"Ubao kwa watu wanaoandika msimbo bila AI, na mbao za umma.","night-watch.name":"Mlinzi wa usiku","night-watch.line":"Mlinzi na Scrum Master huweka timu kwenye kazi ukiwa umelala.","p-more.name":"Mengine yote","p-more.line":"Mawazo madogo yanayosubiri zamu yake.","p-android.name":"Simu na Android","p-android.line":"Fikia ubao wako kutoka kwenye simu, kisha programu asilia ya Android.","p-release.name":"Alpha na zaidi","p-release.line":"Alpha iliyofungwa, tovuti hai, kisha beta.","p-languages.name":"Lugha zaidi","p-languages.line":"Zaidi ya lugha mia moja, na hali ya kuzama kwa wanaojifunza.","p-engines.name":"Injini zaidi za AI","p-engines.line":"Chagua Claude, Codex au Gemini kwa kila wakala.","p-pro.name":"Mazoea ya kitaalamu","p-pro.line":"Lebo za hatari, milango ya kuunganisha, kadi za matukio na vizuizi vya usalama.","p-self.name":"Kukutunza wewe","p-self.line":"Hali ya uchovu, vikumbusho vya kujitunza na 4:20.","p-servers.name":"Seva na ukuaji","p-servers.line":"Mipangilio ya seva ya kimataifa, majukumu na kupanga ukuaji.","p-livestream.name":"Ziada za utiririshaji","p-livestream.line":"Gumzo la Twitch, emoji maalum na mwonekano wa umma wa moja kwa moja."},"words":{"button":"📖 Maneno ya kitaalamu","h":"📖 Maneno yaliyoelezwa","intro":"Maneno utakayokutana nayo katika AI-gile, kwa lugha rahisi: kukijenga, kukibadilisha kwa usalama, kukiweka kifanye kazi kwa watu wanaokitumia, na kufanya kazi kama timu pamoja na AI.","search":"Tafuta neno…","none":"Hakuna neno linalolingana.","close":"Funga","count":{"one":"neno {count}","other":"maneno {count}"},"groups":[{"id":"build","name":"🛠️ Kujenga"},{"id":"change","name":"🔀 Kubadilisha kwa usalama"},{"id":"run","name":"🛎️ Kuendesha huduma"},{"id":"team","name":"🤝 Kufanya kazi kama timu (na pamoja na AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Folda ya msimbo ya mradi na historia yake kamili ya commits, mara nyingi huhifadhiwa pia kwenye GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Mstari wa kazi uliotenganishwa kwenye msimbo, ili mabadiliko yafanywe bila kugusa toleo kuu.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Nakala iliyohifadhiwa ya msimbo, pamoja na maelezo mafupi ya kilichobadilika. Unaweza kurudi kwenye moja wakati wowote.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Kutuma nakala zilizohifadhiwa (commits) kutoka kompyuta hii hadi GitHub, ili ziwe na nakala rudufu na zishirikiwe."},{"id":"merge","g":"build","word":"Merge","text":"Kuunganisha mabadiliko ya branch kurudi kwenye toleo kuu."},{"id":"pr","g":"build","word":"Pull request","text":"Kuomba mabadiliko ya branch yakaguliwe na kuunganishwa kwenye toleo kuu.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kupanga msimbo bila kubadilisha unachofanya: faili ndogo zaidi, majina wazi zaidi, marudio machache."},{"id":"bug","g":"build","word":"Bug","text":"Kitu kisichofanya kazi kama kinavyopaswa.","also":["bugs"]},{"id":"test","g":"build","word":"Jaribio","text":"Kujaribu kazi iliyokamilika ili kuona kama inafanya iliyoombwa, kabla ya kuikubali.","also":["test","tests","majaribio","jaribu","kujaribu","uijaribu"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Kifupi cha quality assurance, yaani uhakikisho wa ubora: ukaguzi wa kiotomatiki unaofanyika kabla kitu chochote hakijaenda hewani. QA ikiwa nyekundu, kuna kitu kimeshindwa, na hakiwezi kwenda hewani mpaka kirekebishwe.","also":["ukaguzi wa ubora","uhakikisho wa ubora"]},{"id":"deploy","g":"change","word":"Deploy","text":"Kuweka toleo jipya hewani, kwa mfano kwenye seva ambako watu wanalitumia."},{"id":"release","g":"change","word":"Toleo","text":"Kifurushi chenye jina cha kazi iliyokamilika kinachoenda hewani pamoja, na maelezo mafupi ya kilichobadilika. 🚀 Matoleo huandika maelezo kutoka kwenye kadi zilizokamilika.","also":["matoleo","release"]},{"id":"rollback","g":"change","word":"Rudisha nyuma","text":"Kurudi kwenye toleo la mwisho lililofanya kazi pale jipya linaposababisha matatizo. Katika AI-gile hutengeneza orodha ya hatua za kutendua zilizoandikwa kwenye kila badiliko.","also":["rollback","kurudisha nyuma","imerudishwa nyuma"]},{"id":"live","g":"change","word":"Hewani","text":"Toleo halisi ambalo watu wanatumia, tofauti na nakala ya kujaribia mambo. Wasanidi programu pia huliita production.","also":["live","production","uzalishaji"],"noTip":1},{"id":"change","g":"change","word":"Badiliko","text":"Badiliko lililopangwa kwa kitu ambacho watu wanakitegemea, likiandikwa kwanza: nini, kwa nini, hatari, lini, na jinsi ya kulitendua. Lianzishe kwa 🔀 Omba badiliko.","also":["mabadiliko","ombi la badiliko","maombi ya mabadiliko"],"noTip":1},{"id":"risk","g":"change","word":"Hatari","text":"Kitu kinachoweza kwenda vibaya, kilichopewa alama kulingana na uwezekano wake na ubaya wake. ⚠️ Hatari huziweka kwenye orodha moja, alama ya juu kwanza, kila moja ikiwa na tarehe ya kuiangalia tena.","also":["hatari nyingi","rejista ya hatari"]},{"id":"chgwin","g":"change","word":"Dirisha la mabadiliko","text":"Nyakati ambazo mabadiliko yanaruhusiwa kwenda hewani, kama jioni tulivu ya Jumanne. Nje ya dirisha kadi ya badiliko haiwezi kukamilishwa, isipokuwa ni dharura.","also":["madirisha ya mabadiliko","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Kura ya haraka kabla tu badiliko halijaenda hewani: kila mtu anayepaswa kuidhinisha anasema Go au No go. Linaendelea tu wakikubaliana.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Idhini","text":"Kusubiri ndiyo kabla kazi haijaanza. Kadi aliyoiomba rafiki, au badiliko, husubiri katika ✅ Idhini mpaka uikubali au uikatae.","also":["idhini nyingi","kuidhinisha"]},{"id":"quiettime","g":"change","word":"Wakati wa utulivu","text":"Kipindi, kama matangazo ya moja kwa moja, onyesho au usiku, ambapo hakuna kinachokwenda hewani. Timu zinaendelea kufanya kazi na kujaribu, lakini kwenda hewani kunasubiri mpaka kiishe. Mahali pengine huitwa change freeze.","also":["nyakati za utulivu","kusimamisha mabadiliko","change freeze"]},{"id":"service","g":"run","word":"Huduma","text":"Kitu ulichojenga ambacho watu wanakitegemea, kama tovuti au programu, kinachotunzwa ili kiendelee kufanya kazi. Weka alama kwenye “Mradi huu ni huduma” na useme kinatoa nini, nani anakitumia na nani yuko zamu.","also":["huduma nyingi","service"]},{"id":"uptime","g":"run","word":"Ukaguzi wa upatikanaji","text":"Ukaguzi wa kiotomatiki, kila baada ya dakika chache, kwamba huduma yako bado inajibu. Ukishindwa mara kadhaa mfululizo, AI-gile hufungua kadi ya tukio yenyewe.","also":["uptime","upatikanaji","ukaguzi wa uptime"]},{"id":"statuspage","g":"run","word":"Ukurasa wa hali","text":"Ukurasa wa umma unaoonyesha kama huduma inafanya kazi (kijani, machungwa au nyekundu) pamoja na habari ya karibuni, ili wanaoitumia waweze kuangalia badala ya kuuliza.","also":["kurasa za hali","status page"]},{"id":"incident","g":"run","word":"Tukio","text":"Kitu kilichoharibika kwa watu wanaokitumia sasa hivi, kama tovuti kutofunguka. Kadi ya 🔥 tukio hupita mbele ya foleni: kuirudisha ifanye kazi huja kwanza.","also":["matukio","incident"]},{"id":"major","g":"run","word":"Tukio kubwa","text":"Tukio kubwa: watu wengi wameathirika, au pesa au data ziko hatarini. Kitufe kimoja huweka kila timu juu yake (kundi), humwamsha aliye zamu na huomba habari ya hali kila dakika 30.","also":["matukio makubwa","major incident"]},{"id":"oncall","g":"run","word":"Zamu","text":"Kuwa yule anayejibu kitu kinapoharibika, hata usiku. Kila huduma ina mwanatimu wa zamu anayeamshwa kwanza kwa matukio yake.","also":["aliye zamu","on call","on-call"]},{"id":"replyby","g":"run","word":"Muda wa kujibu","text":"Kadi inaweza kusubiri jibu la kwanza kwa muda gani, kwa mfano saa moja kwa tukio. Baada ya hapo inapata saa nyekundu, ili hakuna kinachosahaulika kimya kimya. Pia huitwa lengo la kujibu.","also":["nyakati za kujibu","lengo la kujibu"]},{"id":"postmortem","g":"run","word":"Uchambuzi wa baada ya tukio","text":"Kuangalia nyuma kwa ufupi baada ya tukio: nini kilitokea, nini kilisaidia na nini cha kubadilisha, bila kumlaumu mtu yeyote. Tukio haliwezi kufungwa bila uchambuzi huu. Mara nyingi huitwa post-mortem.","also":["post-mortem","postmortem","uchambuzi wa tukio"]},{"id":"problem","g":"run","word":"Tatizo","text":"Chanzo kilichojificha nyuma ya tukio moja au zaidi. Kadi ya 🧩 tatizo hukusanya matukio yanayojirudia, ili chanzo kipatikane na kirekebishwe kabisa.","also":["matatizo","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Chanzo kikuu","text":"Sababu halisi kitu kilivyoharibika, si tu kile ulichoona kikienda vibaya. Rekebisha chanzo kikuu na tukio litaacha kujirudia.","also":["vyanzo vikuu","root cause"]},{"id":"workaround","g":"run","word":"Suluhisho la muda","text":"Njia ya kufanya mambo yaendelee mpaka suluhisho halisi liwe tayari, kama kuwasha upya kitu kinapokwama. Huandikwa kwenye kadi ya tatizo ili mtu yeyote asilazimike kulitafuta tena.","also":["masuluhisho ya muda","workaround"]},{"id":"knownerror","g":"run","word":"Kosa linalojulikana","text":"Tatizo ambalo chanzo chake kinaeleweka na lina suluhisho la muda, lakini bado halijarekebishwa. 🧩 Makosa yanayojulikana huyaorodhesha, ili kila mtu atumie suluhisho la muda badala ya kuchimba upya.","also":["makosa yanayojulikana","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Maelekezo ya hatua kwa hatua ya kurekebisha aina ya tatizo linalojulikana, ili lifanyike kwa njia ileile, haraka, kila mara. Baada ya tukio kubwa timu inaweza kupendekeza moja uikubali.","also":["runbooks","mwongozo wa hatua"]},{"id":"backup","g":"run","word":"Nakala rudufu","text":"Nakala iliyohifadhiwa ya data yako ya awali, ya kutegemea kitu kikipotea au kuharibika. AI-gile hutengeneza nakala rudufu ya mbao zako kila siku.","also":["nakala rudufu nyingi","backup","hifadhi nakala"]},{"id":"restore","g":"run","word":"Rejesha","text":"Kurudisha data kutoka kwenye nakala rudufu. Nakala rudufu ina thamani kweli pale tu unapojua inaweza kurejeshwa, kwa hiyo inafaa kujaribu mara kwa mara.","also":["kurejesha","imerejeshwa","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Mawazo na kazi ambazo bado hazijapangwa. Hakuna kinachofanyiwa kazi huko hadi kihamie Za kufanya."},{"id":"sprint","g":"team","word":"Sprint","text":"Kipindi kifupi cha kazi (mara nyingi wiki moja au mbili) chenye seti iliyokubaliwa ya kadi za kumaliza.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Kikao cha haraka: kile ambacho kila mwanatimu amefanya, atakachofanya baadaye, na kinachomzuia.","also":["standup","stand-ups","standups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ubao wenye safu wima (Za kufanya, Zinaendelea, Zimekamilika) ambapo kadi husogea kutoka kushoto kwenda kulia kazi inapoendelea."},{"id":"wip","g":"team","word":"Kikomo cha WIP","text":"Kazi inayoendelea: idadi ya juu ya kadi ambazo safu wima inapaswa kubeba, ili timu ikamilishe mambo kabla ya kuanza mengine.","also":["WIP"]},{"id":"dod","g":"team","word":"Maana ya Imekamilika","text":"Orodha fupi ya timu ya maana ya “imekamilika”, kama imejaribiwa na kuelezwa, kabla kadi haijakabidhiwa kwako. Pacha wake, Maana ya Tayari, husema lini kadi iko wazi vya kutosha kuanza.","also":["Definition of Done","Maana ya Tayari","Definition of Ready"]},{"id":"testpile","g":"team","word":"Rundo la majaribio","text":"Kadi zilizokamilika zinazosubiri uzijaribu, moja baada ya nyingine. Kubali moja au irudishe pamoja na maelezo, na inayofuata itakuja.","also":["marundo ya majaribio"]},{"id":"retro","g":"team","word":"Retro","text":"Kuangalia nyuma jinsi timu inavyofanya kazi, ili kukubaliana jambo moja la kufanya vizuri zaidi. Katika AI-gile retro hupendekeza badiliko kwa njia za kazi za timu, nawe unasema Endelea au Bado.","also":["retros","retrospective","kuangalia nyuma"]},{"id":"peerreview","g":"team","word":"Ukaguzi wa wenzako","text":"Jozi ya pili ya macho: AI nyingine inakagua kazi ya kila kadi kabla haijakufikia, ili makosa machache yapite.","also":["peer review","ukaguzi wa msimbo","code review"]},{"id":"swarm","g":"team","word":"Kundi","text":"Kila mtu kazini: kila timu inaacha kazi nyingine kusaidia mradi mmoja wa haraka mpaka utatuliwe. Miradi mingine inasubiri kwa sasa.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Yule anayefanya kazi iendelee kutiririka: anaona kadi zilizokwama, anazihimiza timu na anakukumbusha kinachosubiri. Katika AI-gile Lead Scrum Master hufanya hivi katika kila mradi.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Wakala","text":"AI inayofanya kazi yenyewe kwenye jukumu: husoma msimbo, hufanya mabadiliko, huendesha ukaguzi na kutoa taarifa.","also":["agent","agents","mawakala"]},{"id":"token","g":"team","word":"Tokeni","text":"Kipimo kinachotumika kuhesabu matumizi ya AI: takriban herufi chache za maandishi yanayosomwa au kuandikwa. Kadiri unavyotumia tokeni chache, ndivyo mpango wako unavyobaki zaidi.","also":["token","tokens","tokeni"]},{"id":"hook","g":"team","word":"Hook","text":"Amri ndogo inayojiendesha yenyewe wakati maalum, mf. kipindi cha AI kinapoanza, ili timu isikie maoni yako.","also":["hooks"]}]}};
